/*
 * Overlay file adding a Bosch BME280 sensor on i2c0 (address 0x76)
 * with an active-low interrupt on gpio0 pin 15.
 */

/ {
    &i2c0 {
        bme280@76 {
            compatible = "bosch,bme280";
            reg = <0x76>;
            status = "okay";
            interrupt-parent = <&gpio0>;
            interrupts = <15 GPIO_ACTIVE_LOW>;
        };
    };
};
